<template>
    <div class="layout-px-spacing">  
            <ul class="navbar-nav flex-row mt-2">
                <li>
                    <div class="page-header">
                        <nav class="breadcrumb-one" aria-label="breadcrumb">
                            <ol class="breadcrumb">
                                <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                                <li class="breadcrumb-item active" aria-current="page"><span>Services</span></li>
                            </ol>
                        </nav>
                    </div>
                </li>
            </ul>

            <h3 class="text-center">SITE LABOUR ATTENDANCE FROM {{ start_date }} TO {{ end_date }}</h3>
            <!-- <span v-if="loading" v-html="waitIndicator()"></span> -->
<div class="d-flex me-4 mt-2 align-items-center flex-wrap">
  
  <button class="btn btn-success me-2" @click="printLabourAttendance(attendances)">
    <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" fill="currentColor" class="bi bi-printer" viewBox="0 0 16 16">
      <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1"/>
      <path d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1"/>
    </svg>
  </button>

  <input type="date" v-model="start_date" class="form-control me-2" style="max-width: 180px;">
  <input type="date" v-model="end_date" class="form-control me-2" style="max-width: 180px;">

  <Multiselect
    v-model="project"
    :options="projects"
    label="short_name"
    placeholder="Select Project"
    :searchable="true"
    :allow-empty="false"
    class="me-2"
    style="min-width: 200px;max-width: 300px;"
  />

  <button class="btn btn-primary me-2" @click="getLabourAttendance()">Search</button>
  <button 
  class="btn btn-primary me-2"
  @click="request_payment = !request_payment;getLabourAttendance()"
  v-if="!request_payment"
>
Create Request Draft
</button>


  <!-- <Multiselect
    v-model="draft_options"
    :options="['NEW DRAFT','EXISTING DRAFT']"
    placeholder="Select Option"
    :searchable="true"
    :allow-empty="false"
    class="me-2"
    style="min-width: 200px;max-width: 300px;"
  /> -->


  <Multiselect
    v-if="request_payment"
    v-model="draft"
    :options="drafts"
    label="date"
    placeholder="Select Draft"
    :searchable="true"
    :allow-empty="false"
    class="me-2"
    style="min-width: 200px;max-width: 500px;"
  />


<button 
  class="btn btn-success flex-shrink-0"
  @click="openPaymentSummary"
  :disabled="selectedLabours.length === 0"
  data-bs-toggle="modal"
  data-bs-target="#payment-request-modal"
  v-if="request_payment"
>
   Save Draft
</button>

<button 
  v-if="request_payment"
  class="btn btn-secondary ms-2"
  @click="toggleSelectAll"
>
  {{ selectedLabours.length === attendances.length ? '❌' : '✔' }}
</button>

</div>


      
        <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <div v-if="loading" v-html="tableShimmer()"></div>
                        <v-client-table v-else :data="attendances" :columns="columns" :options="table_option">
                            <template #status="props">
                                <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                                    {{ props.row.status.name }}
                                </span>
                            </template>
                            <template #actions="props">
                                <input 
                                v-if="request_payment"
                            type="checkbox" 
                            :value="props.row" 
                            v-model="selectedLabours"
                           />
                            </template>
                          
                           
                         

                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

  <!-- payment modal starts -->
<div class="modal fade mymodal" id="payment-request-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="paymentRequestModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="paymentRequestModalLabel">Create Request Draft</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closePaymentModal()"></button>
      </div>
      <form @submit.prevent="submitPaymentRequest()">
        <div class="modal-body">
            <div class="row mb-3">
              <div class="col-md-6 my-2 ">
                <p><b>Selected labours:</b> {{ paymentSummary?.count }}</p>
              </div>
              <div class="col-md-6 my-2">
                <p><b>Total Amount:</b> {{ formatNumber(paymentSummary?.total) }}</p>
              </div>

              <div class="col-md-12">
                <label class="form-label">Summary Description</label>
                <input type="text" v-model="paymentDescription" class="form-control" placeholder="Enter summary description">
              </div>

              <div class="col-md-12">
                <hr>
                <div v-if="warning_message" class="alert alert-danger" role="alert">
                   {{ warning_message }}
                </div>
              </div>

              <div class="col-md-12">
                <div class="panel p-0">
                  <div class="custom-table">
                    <v-client-table
                      v-if="selectedLabours.length > 0"
                      :data="selectedLabours"
                      :columns="paymentColumns"
                      :options="table_option"
                    />
                  </div>
                </div>
              </div>
            
          </div>
        </div>
         <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="closePaymentModal()" id="close_payment_request">Close</button>
          <button type="submit" class="btn btn-primary" :disabled="submittingPaymentRequest">
            <span v-if="submittingPaymentRequest" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            submit
          </button>
        </div> 
      </form>
    </div>
  </div>
</div>
  <!-- payment modal ends -->


    </div>
</template>
<style>
    .table3 .actions svg {
        padding: 2px;
    }
</style>
<script setup>
    import { onMounted, ref ,inject ,watch,computed,watchEffect } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Labour Attendance' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
import { start } from '@popperjs/core';
    import { useRouter } from 'vue-router';
    const router = useRouter();
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
  const request_payment = ref(false);
    
const paymentSummary = computed(() => {
  return {
    count: selectedLabours.value.length,
    total: selectedLabours.value.reduce(
      (sum, row) => sum + Number(row.rate_original),
      0
    )
  }
})

const toggleSelectAll = () => {
  if (selectedLabours.value.length === attendances.value.length) {
    selectedLabours.value = []
  } else {
    selectedLabours.value = [...attendances.value]
  }
}

const paymentDescription = ref('')
const openPaymentSummary = () => {
}

    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const waitIndicator = inject('waitIndicator')
    const showConfirmation = inject('showConfirmation')
    const formatNumber = inject('formatNumber')
    const formatDate =inject('formatDate')
    const tableShimmer = inject('tableShimmer');
    const name = ref('');
    const loading = ref(false);
    const selectedLabours = ref([]);
    const columns = ref(['Sno', 'full_name','type','rate','project','supervisor','task','status','date','actions']);
    const paymentColumns = ref(['Sno', 'full_name', 'type', 'rate', 'project','task', 'date']);
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 , 100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['id', 'service_name'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

const attendances = ref([])
const date = ref(new Date().toISOString().slice(0, 10))
const start_date = ref(new Date().toISOString().slice(0, 10))
const end_date = ref(new Date().toISOString().slice(0, 10))
const getLabourAttendance = async () => {
  getDrafts()
  loading.value = true
  try {
    const params = {
      start_date: start_date.value,
      end_date: end_date.value
    }

    if (project.value?.short_name) {
      params.project_id = project.value.id
    }

    const response = await axiosInstance.get('labour-attendants', { params })

    attendances.value = response.data.map((item, index) => ({
      ...item,
      Sno: index + 1,
      full_name: item.labour_name,
      type: item.labour_type?.name,
      rate: formatNumber(item.labour_type?.rate),
      rate_original: item.labour_type?.rate,
      project: item.project?.short_name,
      supervisor: item.registrar?.name,
      date: formatDate( item.date || item.created_at)
    }))
  } catch (error) {
    showError(error.message)
  } finally {
    loading.value = false
  }
}

const projects = ref([''])
const project = ref(null)


const getProjects = async () => {
   try{
     const response = await axiosInstance.get('projects')
     projects.value = response.data
   }catch(error){
    showError(error.message)
    console.log(error)
   }finally{

   }
};

const submittingPaymentRequest = ref(false)
const warning_message = ref('')
const submitPaymentRequest = async () => {

  submittingPaymentRequest.value = true;
   const payload = {
      ...(draft.value.id ? { request_id: draft.value.id } : {}),
      project_id: project?.value?.id ?? '',
      start_date: start_date.value,
      end_date: end_date.value,
      issuer_id: JSON.parse(localStorage.getItem('user')).id,
      description: paymentDescription.value,
      labours: selectedLabours.value.map(l => ({
        attendance_id: l.id,
        labour_id: l.labour_id,
        quantity: l.rate_original,
      }))
    };

  try {
    await axiosInstance.post('labour-payment-requests', payload);
    showMessage('Payment request created successfully');
    document.getElementById('close_payment_request').click();
    router.push('/hr/labour/vouchers');

  } catch (error) {
    console.log(error);
    if(error.status != 422){
       showError(error.message); 
    }
    warning_message.value = error.response.data
  } finally {
    submittingPaymentRequest.value = false;
  }
};

const closePaymentModal = () => {
  selectedLabours.value = [];
  paymentDescription.value = '';
  request_payment.value = false;
  warning_message.value = ''
}


const printLabourAttendance = async (data) => {
  try {
    const items = data || []

    const totalCost = items.reduce((sum, item) => {
      return sum + Number(item?.labour_type?.rate || 0)
    }, 0)

    const iframe = document.createElement('iframe')
    iframe.style.display = 'none'
    document.body.appendChild(iframe)

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<style>
  body { font-family: 'Courier New', monospace; margin: 20px; font-size: 8px; }
  .company-title { text-align: center; font-size: 9px; }
  .company-title h1 { font-size: 14px; margin: 5px 0; }
  .title { text-align: center; font-size: 12px; margin: 8px 0; font-weight: bold; }
  table { width: 100%; border-collapse: collapse; margin-top: 8px; font-size: 9px; }
  th, td { border: 1px solid #000; padding: 3px 4px; }
  th { background-color: #f0f0f0; font-weight: bold; }
  .text-right { text-align: right; }
  hr { border: 0; border-top: 1px solid #000; margin: 8px 0; }
</style>
</head>
<body>

<div class="company-title">
  <h1>COPEX CONTRACTORS CO.LTD</h1>
  <div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
  <div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
  <div><b>Email:</b> info@copexcontractors.co.tz</div>
  <div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
</div>

<hr>

<div class="title">${project.value?.short_name ?? 'ALL'} SITE LABOUR ATTENDANCE REPORT </div>
<div class="title">FROM ${start_date.value} TO ${end_date.value} </div>

<hr>

<table>
<thead>
<tr>
  <th>S/No.</th>
  <th>Labour</th>
  <th>Type</th>
  <th>Task</th>
  <th>Time Reported</th>
  <th>Date</th>
  <th>Status</th>
  <th>Cost Per Day</th>
</tr>
</thead>
<tbody>
${items.map((item, index) => `
<tr>
  <td>${index + 1}</td>
  <td>${item.labour_name || 'N/A'}</td>
  <td>${item?.labour_type?.name || 'N/A'}</td>
  <td>${item.task || 'N/A'}</td>
  <td>${item.reporting_time || 'N/A'}</td>
  <td>${item.date || item.created_at || 'N/A'}</td>
  <td>${item?.status?.name || 'N/A'}</td>
  <td class="text-right">${formatNumber(item?.labour_type?.rate || 0)}</td>
</tr>
`).join('')}
<tr style="font-weight:bold;">
  <td colspan="7" class="text-right">TOTAL COST :</td>
  <td class="text-right">${formatNumber(totalCost)}</td>
</tr>
</tbody>
</table>

<div style="margin-top: 15px; font-size: 7px;">
  <p><strong>Report Generated:</strong> ${new Date().toLocaleString()}</p>
  <p><strong>Generated By:</strong> ${JSON.parse(localStorage.getItem('user'))?.name}</p>
</div>

</body>
</html>
`

    const iframeDoc = iframe.contentWindow.document
    iframeDoc.open()
    iframeDoc.write(printContent)
    iframeDoc.close()

    iframe.onload = () => {
      iframe.contentWindow.focus()
      iframe.contentWindow.print()
      setTimeout(() => document.body.removeChild(iframe), 1000)
    }
  } catch (error) {
    showError(`Failed to print report: ${error.message}`)
  }
}

const drafts = ref([])
const draft = ref('')
const draft_options = ref('')
const getDrafts = async()=>{
  const response = await axiosInstance.get(`draft-requests?project_id=${project?.value?.id ?? ''}`)
  drafts.value = response.data.map((item)=>({
    ...item,
    date : item.start_date +' to '+ item.end_date
  }))
}
    onMounted(() => {
        getLabourAttendance();
        getProjects()
    });
</script>
